/*
 * Seven Kingdoms Android port: first-launch data extraction.
 *
 * The game opens its data with plain stdio relative paths after chdir()ing into SKDATA, and APK
 * assets cannot be fopen()ed. So the assets are copied once to
 *     <SDL_AndroidGetInternalStoragePath()>/data/
 * and SKDATA is pointed there.
 *
 * APK layout (generated by scripts/stage-assets.sh):
 *     manifest.txt        one relative file path per line
 *     data_version.txt    version stamp, e.g. "2.15.7-1"
 *     gamedata/<path>     the files listed in the manifest
 *
 * The asset root is deliberately NOT called "data": SDL_RWFromFile() tries a relative path under
 * the internal storage directory before the APK, so "data/X" would resolve to the extracted copy.
 */
#ifdef __ANDROID__

#include <SDL.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include <string>
#include <vector>

#include "sk_android.h"

static const char *const APP_TITLE = "Seven Kingdoms";
static const char *const ASSET_PREFIX = "gamedata/";
static const char *const STAMP_NAME = "data_version.txt";

static void fail(const std::string &reason)
{
	SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "FATAL: %s", reason.c_str());
	SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_ERROR, APP_TITLE, reason.c_str(), NULL);
	exit(1);
}

static std::string trim(const std::string &s)
{
	size_t b = s.find_first_not_of(" \t\r\n");
	if (b == std::string::npos)
		return "";
	size_t e = s.find_last_not_of(" \t\r\n");
	return s.substr(b, e - b + 1);
}

// Read a whole file (asset or filesystem) into a string. Returns false if it cannot be opened.
static bool read_all(const std::string &path, std::string &out)
{
	SDL_RWops *rw = SDL_RWFromFile(path.c_str(), "rb");
	if (!rw)
		return false;
	out.clear();
	char buf[4096];
	size_t n;
	while ((n = SDL_RWread(rw, buf, 1, sizeof(buf))) > 0)
		out.append(buf, n);
	SDL_RWclose(rw);
	return true;
}

// mkdir -p for the directory part of a file path.
static bool make_parent_dirs(const std::string &file)
{
	for (size_t i = 1; i < file.size(); i++)
	{
		if (file[i] != '/')
			continue;
		std::string dir = file.substr(0, i);
		if (mkdir(dir.c_str(), 0771) != 0 && errno != EEXIST)
			return false;
	}
	return true;
}

// Copy one APK asset to dest via a temporary name, so an interrupted copy never leaves a
// truncated file under its real name.
static void copy_asset(const std::string &assetPath, const std::string &dest)
{
	SDL_RWops *in = SDL_RWFromFile(assetPath.c_str(), "rb");
	if (!in)
		fail("Cannot read packaged file " + assetPath + ": " + SDL_GetError());

	if (!make_parent_dirs(dest))
		fail("Cannot create directory for " + dest + ": " + strerror(errno));

	std::string tmp = dest + ".tmp";
	SDL_RWops *out = SDL_RWFromFile(tmp.c_str(), "wb");
	if (!out)
		fail("Cannot write " + tmp + ": " + SDL_GetError());

	std::vector<char> buf(256 * 1024);
	size_t n;
	while ((n = SDL_RWread(in, &buf[0], 1, buf.size())) > 0)
	{
		if (SDL_RWwrite(out, &buf[0], 1, n) != n)
			fail("Write failed for " + tmp + " (storage full?): " + SDL_GetError());
	}
	SDL_RWclose(in);
	if (SDL_RWclose(out) != 0)
		fail("Closing " + tmp + " failed (storage full?): " + SDL_GetError());

	if (rename(tmp.c_str(), dest.c_str()) != 0)
		fail("Cannot rename " + tmp + " to " + dest + ": " + strerror(errno));
}

static void write_stamp(const std::string &dest, const std::string &version)
{
	if (!make_parent_dirs(dest))
		fail("Cannot create directory for " + dest + ": " + strerror(errno));
	std::string tmp = dest + ".tmp";
	SDL_RWops *out = SDL_RWFromFile(tmp.c_str(), "wb");
	if (!out)
		fail("Cannot write " + tmp + ": " + SDL_GetError());
	size_t len = version.size();
	if (SDL_RWwrite(out, version.c_str(), 1, len) != len || SDL_RWclose(out) != 0)
		fail("Cannot write the version stamp " + tmp + ": " + SDL_GetError());
	if (rename(tmp.c_str(), dest.c_str()) != 0)
		fail("Cannot rename " + tmp + " to " + dest + ": " + strerror(errno));
}

void sk_android_prepare_data(void)
{
	const char *internal = SDL_AndroidGetInternalStoragePath();
	if (!internal || !*internal)
		fail(std::string("Cannot find the app's storage directory: ") + SDL_GetError());

	std::string dataDir = std::string(internal) + "/data";
	std::string stampPath = dataDir + "/" + STAMP_NAME;

	std::string assetVersion;
	if (!read_all("data_version.txt", assetVersion))
		fail(std::string("The APK has no data_version.txt, it was built without game data: ") + SDL_GetError());
	assetVersion = trim(assetVersion);
	if (assetVersion.empty())
		fail("The APK's data_version.txt is empty.");

	std::string installed;
	bool upToDate = read_all(stampPath, installed) && trim(installed) == assetVersion;

	if (upToDate)
	{
		SDL_LogInfo(SDL_LOG_CATEGORY_APPLICATION,
			"data: %s is up to date (version %s), skipping copy", dataDir.c_str(), assetVersion.c_str());
	}
	else
	{
		SDL_LogInfo(SDL_LOG_CATEGORY_APPLICATION,
			"data: installing version %s (found '%s') into %s",
			assetVersion.c_str(), trim(installed).c_str(), dataDir.c_str());

		std::string manifest;
		if (!read_all("manifest.txt", manifest))
			fail(std::string("The APK has no manifest.txt: ") + SDL_GetError());

		std::vector<std::string> files;
		size_t pos = 0;
		while (pos < manifest.size())
		{
			size_t eol = manifest.find('\n', pos);
			if (eol == std::string::npos)
				eol = manifest.size();
			std::string line = trim(manifest.substr(pos, eol - pos));
			pos = eol + 1;
			if (line.empty())
				continue;
			// never allow a manifest entry to escape the data directory
			if (line[0] == '/' || line.find("..") != std::string::npos)
				fail("Invalid entry in manifest.txt: " + line);
			files.push_back(line);
		}
		if (files.empty())
			fail("The APK's manifest.txt lists no files.");

		Uint32 t0 = SDL_GetTicks();
		for (size_t i = 0; i < files.size(); i++)
		{
			copy_asset(std::string(ASSET_PREFIX) + files[i], dataDir + "/" + files[i]);
			if ((i + 1) % 25 == 0 || i + 1 == files.size())
				SDL_LogInfo(SDL_LOG_CATEGORY_APPLICATION,
					"data: copied %u/%u files", (unsigned)(i + 1), (unsigned)files.size());
		}

		// The stamp goes last: if we die before this point the next launch copies again.
		write_stamp(stampPath, assetVersion);
		SDL_LogInfo(SDL_LOG_CATEGORY_APPLICATION,
			"data: install finished in %u ms", (unsigned)(SDL_GetTicks() - t0));
	}

	if (setenv("SKDATA", dataDir.c_str(), 1) != 0)
		fail(std::string("setenv(SKDATA) failed: ") + strerror(errno));
	SDL_LogInfo(SDL_LOG_CATEGORY_APPLICATION, "data: SKDATA=%s", dataDir.c_str());
}

#endif // __ANDROID__
